import logging
import re

from taf.hw.rf_attenuator.devices.topyoung.topyoung import TopYoung
from taf.hw.rf_attenuator.exceptions import AttenuationReadError


class TopYoungTAS16T16511201SDES(TopYoung):
    MAX_SUPPORTED_ATTENUATION = 120
    MIN_SUPPORTED_ATTENUATION = 0
    _SETM_CMD = r'SETM{}'
    _SETM_RES_OK = r'RESETM:OK'
    _SETM_RES_FAIL = r'RESETM:FAIL'
    _READM_CMD = r'READM{}'
    _READM_RES_OK = r'REREADM([?::\d+,\d+]+)'

    def _verify_set_multiple_ports_attenuation_command_response(self, output):
        if re.search(self._SETM_RES_OK, output):
            return
        self._check_if_set_command_failed(self._SETM_RES_FAIL, output)
        self._check_if_command_error(self._CMD_ERR, output)

    def _set_multiple_ports_decibel_attenuation(self, ports, attenuation_values):
        attenuation_values = [int(x) for x in attenuation_values]
        formatted_ports_values = ''
        for index in range(len(ports)):
            port, attenuation_value = ports[index], attenuation_values[index]
            self._is_channel_valid(port)
            formatted_port_value = ':{},{}'.format(port, attenuation_value)
            formatted_ports_values = formatted_ports_values + formatted_port_value
        output = self._write_and_read(self._SETM_CMD.format(formatted_ports_values))
        self._verify_set_multiple_ports_attenuation_command_response(output)
        logging.info('Channels {} attenuation value is set to {}.'.format(ports, attenuation_values))

    def _verify_read_multiple_ports_attenuation_command_response(self, ports, output):
        self._check_if_command_error(self._CMD_ERR, output)
        search_result = re.search(self._READM_RES_OK, output)
        if search_result:
            original_string = search_result.groups()[0]
            # original string of attenuation values, e.g. ':1,10:2,20:3,30:4,100:5,110:6,120'
            attenuation_values_pattern = re.compile(r'(?:,(\d+):?)+')
            attenuation_values = attenuation_values_pattern.findall(original_string)
            attenuation_values = [int(x) for x in attenuation_values]
            logging.info('Channels {} attenuation is {}.'.format(ports, attenuation_values))
            return attenuation_values
        raise AttenuationReadError('Error in command output: {}'.format(output))

    def _read_multiple_ports_decibel_attenuation(self, ports):
        formatted_ports = ''
        for port in ports:
            self._is_channel_valid(port)
            formatted_port = ':{}'.format(port)
            formatted_ports = formatted_ports + formatted_port
        output = self._write_and_read(self._READM_CMD.format(formatted_ports))
        return self._verify_read_multiple_ports_attenuation_command_response(ports, output)

    def read_ports_attenuation(self, ports):
        return self._read_multiple_ports_decibel_attenuation(ports)
